  FT["PH-H10516"] = {"id":"PH-H10516","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2025/ra_12129_2025.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Upgrading the District Office of the Land Transportation Office in the City of Digos, Province of Davao Del Sur, From Class ‘D’ to Class ‘C’ and Appropriating Funds Therefor","orig":"An Act Upgrading the District Office of the Land Transportation Office in the City of Digos, Province of Davao Del Sur, From Class ‘D’ to Class ‘C’ and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 12129","issuingBody":"Congress of the Philippines","promulgatedDate":"2025-03-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2025/ra_12129_2025.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10516-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The district office of the Land Transportation Office (LTO) in the City of Digos, Province of Davao del Sur is hereby upgraded from Class \"D\" to a Class \"C\" district office."}},{"id":"PH-H10516-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall immediately include in the Department's program the operationalization of the LTO District Office in the City of Digos, the initial funding of which shall be charged against the current year's appropriation of LTO Region XI. Thereafter, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10516-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p150"};
  FT["PH-H10517"] = {"id":"PH-H10517","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2025/ra_12130_2025.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Land Transportation Office Urdaneta District Office Into a Class ‘A’ District Office, Renaming the Same as the Land Transportation Office Binalonan District Office and Appropriating Funds Therefor","orig":"An Act Converting the Land Transportation Office Urdaneta District Office Into a Class ‘A’ District Office, Renaming the Same as the Land Transportation Office Binalonan District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 12130","issuingBody":"Congress of the Philippines","promulgatedDate":"2025-03-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2025/ra_12130_2025.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10517-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) District Office in Urdaneta City, Pangasinan (LTO Urdaneta District Office) is hereby converted into a Class \"A\" LTO district office and renamed as the LTO Binalonan District Office."}},{"id":"PH-H10517-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall immediately include in the Department's program the operationalization of the LTO Binalonan District Office in the Fifth District of Pangasinan, the initial funding of which shall be charged against the current year's appropriation of the LTO Urdaneta District Office. Thereafter, the funding of which shall be included in the annual General Appropriation Act."}},{"id":"PH-H10517-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p150"};
  FT["PH-H10518"] = {"id":"PH-H10518","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2025/ra_12131_2025.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Upgrading the District Office of the Land Transportation Office in Candon City, Province of Ilocos Sur, Into a Class ‘B’ District Office and Appropriating Funds Therefor","orig":"An Act Upgrading the District Office of the Land Transportation Office in Candon City, Province of Ilocos Sur, Into a Class ‘B’ District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 12131","issuingBody":"Congress of the Philippines","promulgatedDate":"2025-03-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2025/ra_12131_2025.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10518-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The district office of the Land Transportation Office (LTO) in Candon City, Province of Ilocos Sur, is hereby upgraded into a Class \"B\" district office."}},{"id":"PH-H10518-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall immediately include in the Department's program the upgrading into a Class \"B\" district office of the LTO District Office in Candon City, Province of Ilkocos Sur, the initial funding of which shall be charged the current year's appropriation of the existing LTO District Office in Candon City. Thereafter, the funding of which shall be included in the annual General Appropriations Acts."}},{"id":"PH-H10518-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p150"};
