  FT["PH-H10540"] = {"id":"PH-H10540","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2025/ra_12153_2025.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Padre Garcia市","en":"An Act Establishing a Land Transportation Office District Office in the Municipality of Padre Garcia, Province of Batangas, and Appropriating Funds Therefor","orig":"An Act Establishing a Land Transportation Office District Office in the Municipality of Padre Garcia, Province of Batangas, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 12153","issuingBody":"Congress of the Philippines","promulgatedDate":"2025-04-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2025/ra_12153_2025.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10540-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a district office of the Land Transportation Office (LTO) to be located in the Municipality of Padre Garcia, Province of Batangas."}},{"id":"PH-H10540-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall immediately include in the Department's program the operationalization of the LTO District Office in the Municipality of Padre Garcia, Province of Batangas, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10540-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p150"};
  FT["PH-H10541"] = {"id":"PH-H10541","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2025/ra_12154_2025.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Catanauan市","en":"An Act Converting the Extension of Office of the Land Transportation Office in the Municipality of Catanauan, Province of Quezon, Into a District Office and Appropriating Funds Therefor","orig":"An Act Converting the Extension of Office of the Land Transportation Office in the Municipality of Catanauan, Province of Quezon, Into a District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 12154","issuingBody":"Congress of the Philippines","promulgatedDate":"2025-04-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2025/ra_12154_2025.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10541-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The extension office of the Land Transportation Office (LTO) located in the Municipality of Catanauan, Province of Quezon, is hereby converted into a district office to be known as the LTO Bondoc Peninsula District Office."}},{"id":"PH-H10541-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall immediately include in the Department's program the operationalization of the LTO Bondoc Peninsula District Office in Province of Quezon, the initial funding of which shall be charged against the current year's appropriation of the LTO Catanauan Extension Office. Thereafter, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10541-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days following the completion of its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p150"};
